}

// GEMM: pipeline+flatten (i,j); fully unroll k with matching partition
for (int i = 0; i < M; ++i) {
  for (int j = 0; j < N; ++j) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_FLATTEN
    T sum = 0;
    for (int k = 0; k < K; ++k) {
#pragma HLS UNROLL
      sum += A[i][k] * B[k][j];
    }
    C[i][j] = sum;
  }
}
// Non-GEMM small inner under a truly outer pipeline:
OUTER: for (int i = 0; i < N; ++i) {
