LOOP: for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE II=1
    ... buf[i] ... buf[i + 1] ...
}

data_t buf[TILE];
#pragma HLS ARRAY_PARTITION variable=buf cyclic factor=UNROLL_FACTOR dim=1

for (int i = 0; i < TILE; i += UNROLL_FACTOR) {
#pragma HLS PIPELINE II=1
    lane_loop: for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
        int idx = i + lane;
        ... buf[idx] ...
    }
}

const int UF = 4;
double partial[UF];
#pragma HLS ARRAY_PARTITION variable=partial complete
for (int p = 0; p < UF; p++) {
#pragma HLS UNROLL
    partial[p] = 0.0;
}
for (int k = 0; k < TILE_SIZE; k += UF) {
#pragma HLS PIPELINE II=1
    for (int p = 0; p < UF; p++) {
#pragma HLS UNROLL
        if (k + p < j) partial[p] += expr(k + p);
    }
}
double sum = 0; for (int p = 0; p < UF; p++) { #pragma HLS UNROLL sum += partial[p]; }

#pragma HLS ARRAY_PARTITION variable=local_A complete dim=2
#pragma HLS ARRAY_PARTITION variable=local_B complete dim=2
// optional: partition local_C cyclic/complete on dim=2 if needed for II
scale: for (int i = 0; i < N; ++i) {
  for (int j = 0; j < N; ++j) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_FLATTEN
    if (j <= i) local_C[i][j] *= beta;
  }
}
update: for (int i = 0; i < N; ++i) {
  for (int j = 0; j < N; ++j) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_FLATTEN
    if (j <= i) {
      double sum = 0.0;
      for (int k = 0; k < M; ++k) {
#pragma HLS UNROLL
        sum += local_A[j][k] * local_B[i][k] + local_B[j][k] * local_A[i][k];
      }
      local_C[i][j] += alpha * sum;
    }
  }
}

data_t old_buf[TILE];
data_t new_buf[TILE];

compute: for (int i = 0; i < TILE; ++i) {
#pragma HLS PIPELINE II=1
    new_buf[i] = update_from_old(old_buf, i);
}

